/* The full bill of materials — every line item, with a hover preview.
 *
 * Data: window.MABEL_BOM.core (49 audited lines, generated by BOM/tools/build_bom.py).
 *
 * Preview image resolution order:
 *   1. assets/bom/img/<ref>.jpg          — a real photo, if one has been added
 *   2. a drawn category illustration     — inline SVG, chosen from the item name
 *
 * The drawn fallback exists because we do not ship vendor product photos we
 * do not own. Drop a JPG named after the ref into assets/bom/img/ and this
 * picks it up automatically — no code change.
 */
(function () {
  'use strict';
  var host = document.getElementById('bomTable');
  if (!host || !window.MABEL_BOM || !window.MABEL_BOM.core) return;

  var CORE = window.MABEL_BOM.core;
  var INK = '#151820', OR = '#F0762E', YEL = '#F2C94C', BLUE = '#23577E',
      GRN = '#2E7D4F', RUST = '#C6301A', PAPER = '#FDF6E2', STEEL = '#B9B2A0';

  /* ── drawn part illustrations, keyed by what the line actually is ────── */
  function svg(inner) {
    return '<svg viewBox="0 0 200 140" aria-hidden="true">' +
      '<rect x="1.5" y="1.5" width="197" height="137" rx="7" fill="#F1E6C6" ' +
      'stroke="' + INK + '" stroke-width="3"/>' + inner + '</svg>';
  }
  var ART = {
    swerve: function () {
      return svg('<circle cx="100" cy="86" r="30" fill="' + INK + '"/>' +
        '<circle cx="100" cy="86" r="12" fill="' + STEEL + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<rect x="72" y="30" width="56" height="26" rx="5" fill="' + PAPER + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<rect x="88" y="52" width="24" height="14" fill="' + OR + '" stroke="' + INK + '" stroke-width="3"/>');
    },
    bldc: function () {
      return svg('<circle cx="100" cy="70" r="40" fill="' + STEEL + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<circle cx="100" cy="70" r="21" fill="' + PAPER + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<circle cx="100" cy="70" r="8" fill="' + OR + '" stroke="' + INK + '" stroke-width="2.5"/>' +
        '<rect x="56" y="98" width="88" height="12" rx="4" fill="' + INK + '"/>');
    },
    servo: function () {
      return svg('<rect x="62" y="34" width="76" height="72" rx="6" fill="' + INK + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<rect x="70" y="42" width="60" height="34" rx="3" fill="' + STEEL + '"/>' +
        '<circle cx="100" cy="92" r="12" fill="' + PAPER + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<path d="M138 60h22M138 72h22" stroke="' + OR + '" stroke-width="4" stroke-linecap="round"/>');
    },
    lift: function () {
      return svg('<rect x="84" y="16" width="32" height="96" fill="' + STEEL + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<rect x="92" y="26" width="16" height="76" fill="' + PAPER + '" stroke="' + INK + '" stroke-width="2.5"/>' +
        '<path d="M150 108V32M141 44l9-14 9 14" stroke="' + GRN + '" stroke-width="5" fill="none" stroke-linecap="round"/>' +
        '<rect x="60" y="112" width="80" height="14" rx="4" fill="' + INK + '"/>');
    },
    camera: function () {
      return svg('<rect x="46" y="46" width="108" height="52" rx="9" fill="' + INK + '"/>' +
        '<circle cx="76" cy="72" r="16" fill="' + PAPER + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<circle cx="76" cy="72" r="7" fill="' + BLUE + '"/>' +
        '<circle cx="124" cy="72" r="16" fill="' + PAPER + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<circle cx="124" cy="72" r="7" fill="' + BLUE + '"/>' +
        '<rect x="92" y="34" width="16" height="12" fill="' + OR + '"/>');
    },
    lidar: function () {
      return svg('<circle cx="100" cy="76" r="34" fill="' + INK + '"/>' +
        '<circle cx="100" cy="76" r="18" fill="' + STEEL + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<path d="M100 76 L44 50M100 76 L156 50M100 76 L52 108M100 76 L148 108" ' +
        'stroke="' + RUST + '" stroke-width="2.5" stroke-dasharray="5 4"/>');
    },
    compute: function () {
      return svg('<rect x="44" y="40" width="112" height="66" rx="6" fill="' + INK + '"/>' +
        '<rect x="60" y="54" width="80" height="38" rx="3" fill="' + STEEL + '"/>' +
        '<rect x="72" y="64" width="56" height="18" fill="' + GRN + '"/>' +
        '<path d="M44 62H26M44 76H26M156 62h18M156 76h18" stroke="' + INK + '" stroke-width="4" stroke-linecap="round"/>');
    },
    board: function () {
      return svg('<rect x="40" y="42" width="120" height="60" rx="4" fill="' + GRN + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<rect x="86" y="60" width="30" height="24" fill="' + INK + '"/>' +
        '<path d="M52 52h18M52 62h18M52 72h12M130 52h18M130 62h18" stroke="' + YEL + '" stroke-width="3" stroke-linecap="round"/>' +
        '<circle cx="50" cy="94" r="4" fill="' + PAPER + '"/><circle cx="150" cy="94" r="4" fill="' + PAPER + '"/>');
    },
    sheet: function () {
      return svg('<path d="M40 96 L74 40 H150 L116 96 Z" fill="' + STEEL + '" stroke="' + INK + '" stroke-width="3" stroke-linejoin="round"/>' +
        '<circle cx="82" cy="72" r="5" fill="#F1E6C6" stroke="' + INK + '" stroke-width="2.5"/>' +
        '<circle cx="108" cy="60" r="5" fill="#F1E6C6" stroke="' + INK + '" stroke-width="2.5"/>' +
        '<circle cx="98" cy="86" r="5" fill="#F1E6C6" stroke="' + INK + '" stroke-width="2.5"/>');
    },
    printed: function () {
      return svg('<path d="M56 100 L100 40 L144 100 Z" fill="' + OR + '" stroke="' + INK + '" stroke-width="3" stroke-linejoin="round"/>' +
        '<path d="M64 92h72M72 80h56M80 68h40" stroke="' + INK + '" stroke-width="2" opacity="0.55"/>' +
        '<rect x="52" y="102" width="96" height="9" rx="3" fill="' + INK + '"/>');
    },
    cable: function () {
      return svg('<path d="M40 96 C70 96 70 44 100 44 C130 44 130 96 160 96" stroke="' + INK + '" ' +
        'stroke-width="9" fill="none" stroke-linecap="round"/>' +
        '<rect x="30" y="86" width="18" height="20" rx="3" fill="' + YEL + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<rect x="152" y="86" width="18" height="20" rx="3" fill="' + YEL + '" stroke="' + INK + '" stroke-width="3"/>');
    },
    power: function () {
      return svg('<rect x="52" y="46" width="96" height="56" rx="6" fill="' + INK + '"/>' +
        '<rect x="62" y="56" width="76" height="36" rx="3" fill="' + STEEL + '"/>' +
        '<path d="M104 58 L88 78h12l-4 16 18-22h-12z" fill="' + YEL + '" stroke="' + INK + '" stroke-width="2"/>' +
        '<rect x="70" y="38" width="18" height="10" fill="' + RUST + '"/>');
    },
    fastener: function () {
      return svg('<rect x="92" y="34" width="16" height="66" fill="' + STEEL + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<path d="M84 46h32M84 56h32M84 66h32M84 76h32" stroke="' + INK + '" stroke-width="2"/>' +
        '<path d="M78 26 L122 26 L114 40 L86 40 Z" fill="' + INK + '"/>' +
        '<rect x="76" y="100" width="48" height="14" rx="3" fill="' + OR + '" stroke="' + INK + '" stroke-width="3"/>');
    },
    screen: function () {
      return svg('<rect x="38" y="36" width="124" height="76" rx="6" fill="' + INK + '"/>' +
        '<rect x="48" y="46" width="104" height="56" rx="3" fill="' + BLUE + '"/>' +
        '<circle cx="82" cy="70" r="9" fill="' + PAPER + '"/><circle cx="118" cy="70" r="9" fill="' + PAPER + '"/>' +
        '<circle cx="84" cy="68" r="4" fill="' + INK + '"/><circle cx="120" cy="68" r="4" fill="' + INK + '"/>');
    },
    generic: function () {
      return svg('<rect x="60" y="46" width="80" height="56" rx="6" fill="' + STEEL + '" stroke="' + INK + '" stroke-width="3"/>' +
        '<path d="M60 66h80M84 46v56" stroke="' + INK + '" stroke-width="2.5" opacity="0.6"/>' +
        '<circle cx="118" cy="84" r="7" fill="' + OR + '" stroke="' + INK + '" stroke-width="2.5"/>');
    }
  };

  var RULES = [
    [/swerve|wheel|maxswerve/i, 'swerve'],
    [/lift column|leadscrew|flexispot/i, 'lift'],
    [/dm\d|damiao|foc|joint (module|motor)|torso actuator|bldc/i, 'bldc'],
    [/servo|feetech|hl\d|dynamixel/i, 'servo'],
    [/zed|realsense|arducam|camera|lens/i, 'camera'],
    [/lidar|rplidar/i, 'lidar'],
    [/jetson|mini-?pc|orin|thor|nuc/i, 'compute'],
    [/teensy|pico|microcontroller|pcb|board|hub|adapter|converter/i, 'board'],
    [/sheet metal|laser|bracket|plate|extrusion|frame|rail/i, 'sheet'],
    [/print|petg|abs|filament|tpu/i, 'printed'],
    [/cable|wire|harness|connector|loom/i, 'cable'],
    [/battery|power|psu|relay|fuse|bms|charger|e-?stop/i, 'power'],
    [/screw|bolt|nut|washer|bearing|fastener|standoff|insert/i, 'fastener'],
    [/screen|display|touch|matrix|led/i, 'screen']
  ];

  function artFor(row) {
    var hay = (row.item || '') + ' ' + (row.spec || '') + ' ' + (row.section || '');
    for (var i = 0; i < RULES.length; i++) if (RULES[i][0].test(hay)) return RULES[i][1];
    return 'generic';
  }

  var usd = function (n) {
    return '$' + Number(n).toLocaleString('en-US', { maximumFractionDigits: 0 });
  };

  /* ── markup ───────────────────────────────────────────────────────────── */
  var sections = [];
  CORE.forEach(function (r) { if (sections.indexOf(r.section) < 0) sections.push(r.section); });

  host.innerHTML =
    '<div class="bt-bar">' +
      '<input class="bt-search" type="search" placeholder="Search 49 line items…" aria-label="Search the bill of materials">' +
      '<div class="bt-filters"><button class="on" data-sec="">All</button>' +
        sections.map(function (s) {
          return '<button data-sec="' + s.replace(/"/g, '&quot;') + '">' + s + '</button>';
        }).join('') +
      '</div>' +
    '</div>' +
    '<div class="bt-scroll"><table class="bt-table"><thead><tr>' +
      '<th>Ref</th><th>Part</th><th>Spec</th><th class="num">Qty</th>' +
      '<th class="num">Unit</th><th class="num">Ext</th><th>Vendor</th>' +
    '</tr></thead><tbody></tbody></table></div>' +
    '<div class="bt-count"></div>' +
    '<div class="bt-preview" hidden><div class="bt-pv-art"></div>' +
      '<div class="bt-pv-body"><b class="bt-pv-name"></b><span class="bt-pv-spec"></span>' +
      '<span class="bt-pv-price"></span></div></div>';

  var tbody = host.querySelector('tbody');
  var search = host.querySelector('.bt-search');
  var count = host.querySelector('.bt-count');
  var pv = host.querySelector('.bt-preview');
  var pvArt = pv.querySelector('.bt-pv-art');
  var pvName = pv.querySelector('.bt-pv-name');
  var pvSpec = pv.querySelector('.bt-pv-spec');
  var pvPrice = pv.querySelector('.bt-pv-price');

  var filter = { q: '', sec: '' };

  function render() {
    var q = filter.q.toLowerCase();
    var rows = CORE.filter(function (r) {
      if (filter.sec && r.section !== filter.sec) return false;
      if (!q) return true;
      return ((r.item || '') + ' ' + (r.spec || '') + ' ' + (r.vendor || '') + ' ' +
              (r.section || '') + ' ' + (r.ref || '')).toLowerCase().indexOf(q) >= 0;
    });
    tbody.innerHTML = rows.map(function (r) {
      var link = r.link
        ? '<a href="' + r.link + '" target="_blank" rel="noopener">' + (r.vendor || 'link') + ' ↗</a>'
        : (r.vendor || '—');
      return '<tr data-ref="' + r.ref + '">' +
        '<td class="bt-ref">' + r.ref + '</td>' +
        '<td class="bt-item">' + r.item + '</td>' +
        '<td class="bt-spec">' + (r.spec || '—') + '</td>' +
        '<td class="num">' + r.qty + '</td>' +
        '<td class="num">' + usd(r.unit_usd) + '</td>' +
        '<td class="num bt-ext">' + usd(r.ext_usd) + '</td>' +
        '<td class="bt-vendor">' + link + '</td></tr>';
    }).join('');
    var sum = rows.reduce(function (a, r) { return a + (r.ext_usd || 0); }, 0);
    count.innerHTML = '<b>' + rows.length + '</b> of ' + CORE.length + ' lines · ' +
      '<b>' + usd(sum) + '</b>' + (filter.sec ? ' in ' + filter.sec : ' core total');
  }

  var byRef = {};
  CORE.forEach(function (r) { byRef[r.ref] = r; });

  function showPreview(tr, ev) {
    var r = byRef[tr.dataset.ref];
    if (!r) return;
    /* a real photo wins if one has been dropped in; otherwise draw the class */
    var img = new Image();
    var url = 'assets/bom/img/' + r.ref + '.jpg';
    pvArt.innerHTML = ART[artFor(r)]();
    img.onload = function () {
      pvArt.innerHTML = '<img src="' + url + '" alt="">';
    };
    img.src = url;

    pvName.textContent = r.item;
    pvSpec.textContent = (r.spec || '') + (r.vendor ? ' · ' + r.vendor : '');
    pvPrice.innerHTML = r.qty + ' × ' + usd(r.unit_usd) + ' = <b>' + usd(r.ext_usd) + '</b>';
    pv.hidden = false;
    movePreview(ev);
  }

  function movePreview(ev) {
    if (pv.hidden) return;
    var pad = 16, w = pv.offsetWidth, h = pv.offsetHeight;
    var x = ev.clientX + pad, y = ev.clientY + pad;
    if (x + w > window.innerWidth - 8) x = ev.clientX - w - pad;
    if (y + h > window.innerHeight - 8) y = ev.clientY - h - pad;
    pv.style.left = Math.max(8, x) + 'px';
    pv.style.top = Math.max(8, y) + 'px';
  }

  tbody.addEventListener('mouseover', function (e) {
    var tr = e.target.closest('tr[data-ref]');
    if (tr) showPreview(tr, e);
  });
  tbody.addEventListener('mousemove', movePreview);
  tbody.addEventListener('mouseleave', function () { pv.hidden = true; });
  /* keyboard parity: focusing a row shows the same card */
  tbody.addEventListener('focusin', function (e) {
    var tr = e.target.closest('tr[data-ref]');
    if (!tr) return;
    var b = tr.getBoundingClientRect();
    showPreview(tr, { clientX: b.right - 40, clientY: b.bottom });
  });
  tbody.addEventListener('focusout', function () { pv.hidden = true; });

  search.addEventListener('input', function () { filter.q = search.value; render(); });
  host.querySelector('.bt-filters').addEventListener('click', function (e) {
    var b = e.target.closest('button'); if (!b) return;
    filter.sec = b.dataset.sec;
    host.querySelectorAll('.bt-filters button').forEach(function (x) {
      x.classList.toggle('on', x === b);
    });
    render();
  });

  render();
})();
